export default class BaseSyncProvider {
    constructor(config) {
        this.config = config;
    }

    async uploadFile(dataType, file, metadata) {
        throw new Error('uploadFile must be implemented');
    }

    async putFile(url, file, headers = {}) {
        throw new Error('putFile must be implemented');
    }

    async getUpload(dataType) {
        throw new Error('getUpload must be implemented');
    }

    async downloadFile(url) {
        throw new Error('downloadFile must be implemented');
    }

    async downloadMetadata(dataType) {
        throw new Error('downloadMetadata must be implemented');
    }

    async uploadMetadata(metadata) {
        throw new Error('uploadMetadata must be implemented');
    }

    async clean() {
        throw new Error('clean must be implemented');
    }
}
