import { recordDebugLog } from '../../utils/helpers';
import { SYNC } from '../../configs/app';
import {
    getCurrentUserUUID,
    getUserConfig,
    setUserConfig,
    userPublicLocalStorage
} from '../user';
import CustomServerProvider from './providers/customServerProvider';
import { setupTriggers, cleanupTriggers } from './triggers/triggerManager';
import { SyncError, ERROR_CODES } from './errors';
import { checkSyncPermissions } from './utils/permissionChecker';
import {
    handleDownloadOnlySync,
    handleUploadOnlySync,
    handleTwoWaySync
} from './utils/syncOperations';
import { debounce } from 'lodash-es';
import { httpRequestJSON } from '../../utils/http';
import syncLock, { cleanupSyncLock } from '../../utils/syncLock';
import { getServerTime } from '../../utils/serverTime';

class SyncService {
    static instance = null;

    constructor(config) {
        if (!config) {
            throw new Error('Config is required');
        }
        this.config = config;
        this.isInitialized = false;
        this.localCache = null;
        this.provider = null;
        this.retryCount = new Map();
        this.unsubscribers = new Map();
    }

    async ensureInitialized() {
        if (!this.isInitialized) {
            await this.initialize();
        }
        return true;
    }

    async initialize() {
        if (this.isInitialized) {
            return true;
        }

        try {
            if (!this.config) {
                recordDebugLog('[syncService] Config missing, attempting to reload...');
                const newConfig = await this.loadConfig();
                if (!newConfig) {
                    throw new Error('Failed to load sync config');
                }
                this.config = newConfig;
            }

            const { defaultSyncProvider, syncProviders } = this.config;
            if (!defaultSyncProvider) {
                throw new Error('Default sync provider not specified');
            }

            this.localCache = await userPublicLocalStorage('sync');
            await checkSyncPermissions();


            if (defaultSyncProvider === 'custom') {
                const providerConfig = syncProviders?.find(
                    provider => provider.type === 'custom'
                )?.config;

                if (!providerConfig) {
                    throw new Error('Custom provider config not found');
                }
                this.provider = new CustomServerProvider(providerConfig);
            }

            if (this.config.syncMode !== SYNC.MODES.DISABLED) {
                this.unsubscribers = setupTriggers(
                    this.config,
                    dataKey => this.syncData(dataKey)
                );
            }

            this.isInitialized = true;
            return true;
        } catch (error) {
            console.error('Failed to initialize SyncService:', error);
            await this.cleanup();
            throw error;
        }
    }

    async cleanup() {
        recordDebugLog('[syncService] Starting cleanup...');
        this.isInitialized = false;

        const configBackup = { ...this.config };

        try {
            cleanupSyncLock();
        } catch (error) {
            recordDebugLog('[syncService] Error during syncLock cleanup:', error);
        }

        this.retryCount?.clear();

        if (this.unsubscribers?.size > 0) {
            try {
                cleanupTriggers(this.unsubscribers);
            } catch (error) {
                recordDebugLog('[syncService] Error during triggers cleanup:', error);
            }
            this.unsubscribers.clear();
        }

        if (this.provider) {
            try {
                if (typeof this.provider.cleanup === 'function') {
                    await this.provider.cleanup();
                }
            } catch (error) {
                recordDebugLog('[syncService] Error during provider cleanup:', error);
            }
            this.provider = null;
        }

        this.localCache = null;
        this.config = null;

        recordDebugLog('[syncService] Cleanup completed', {
            hadConfig: !!configBackup,
            config: configBackup
        });
    }


    async syncAllData(useDebounce = true) {
        await this.ensureInitialized();
        recordDebugLog('Starting syncAllData...');

        const enabledDataKeys = Object.keys(this.config.syncDataOptions || {})
            .filter(key => this.config.syncDataOptions[key]?.enabled);

        if (!enabledDataKeys.length) {
            recordDebugLog('No enabled sync data options found');
            return;
        }

        recordDebugLog(`Starting sync for: ${enabledDataKeys.join(', ')}`);
        const results = await Promise.allSettled(
            enabledDataKeys.map(key => this.syncData(key, useDebounce))
        );

        const syncTime = Date.now();
        const [uploadFailed, downloadFailed] = results.reduce((acc, result, index) => {
            if (result.status === 'rejected') {
                const error = result.reason;
                const dataKey = enabledDataKeys[index];
                recordDebugLog(`Sync failed for ${dataKey}:`, error);

                if (/upload|compress/.test(error.message)) acc[0].push(dataKey);
                if (/download|decompress/.test(error.message)) acc[1].push(dataKey);
            }
            return acc;
        }, [[], []]);

        await Promise.all([
            this.localCache.set('last_sync_at', syncTime),
            this.localCache.set('last_upload_status', uploadFailed.length ? 'failed' : 'success'),
            this.localCache.set('last_download_status', downloadFailed.length ? 'failed' : 'success')
        ]);

        if (uploadFailed.length) recordDebugLog(`Failed to upload: ${uploadFailed.join(', ')}`);
        if (downloadFailed.length) recordDebugLog(`Failed to download: ${downloadFailed.join(', ')}`);

        recordDebugLog('syncAllData completed');
    }

    async _syncData(dataKey) {
        recordDebugLog(`Starting sync for ${dataKey}...`);
        if (!this.isInitialized) {
            recordDebugLog('Error: SyncService not initialized');
            throw new SyncError(ERROR_CODES.NOT_INITIALIZED);
        }
        if (this.config.syncMode === SYNC.MODES.DISABLED) {
            recordDebugLog('Error: Sync is disabled');
            return;
        }

        if (!this.config.syncDataOptions?.[dataKey]?.enabled) {
            recordDebugLog(`Error: Data type ${dataKey} is disabled`);
            throw new SyncError(ERROR_CODES.DATA_TYPE_DISABLED, {
                dataType: dataKey
            });
        }

        try {
            let now = await getServerTime(this.config.server_time_api);
            switch (this.config.syncMode) {
                case SYNC.MODES.DOWNLOAD_ONLY:
                    await handleDownloadOnlySync({
                        provider: this.provider,
                        localCache: this.localCache,
                        dataKey,
                    });
                    break;
                case SYNC.MODES.UPLOAD_ONLY:
                    await handleUploadOnlySync({
                        provider: this.provider,
                        localCache: this.localCache,
                        dataKey,
                    });
                    break;
                case SYNC.MODES.STAY_SYNCHRONIZED:
                    const success = await handleTwoWaySync({
                        provider: this.provider,
                        localCache: this.localCache,
                        dataKey,
                        now
                    });
                    if (success) {
                        this.retryCount.delete(dataKey);
                    }
                    break;
                default:
                    throw new SyncError(ERROR_CODES.INVALID_SYNC_MODE, {
                        mode: this.config.syncMode
                    });
            }
        } catch (error) {
            recordDebugLog(`Sync error for ${dataKey}:`, error);
            throw error instanceof SyncError ? error : new SyncError(
                /upload|compress/.test(error.message) ?
                    ERROR_CODES.SYNC_UPLOAD_ERROR :
                    ERROR_CODES.SYNC_DOWNLOAD_ERROR,
                {
                    dataType: dataKey,
                    message: error.message
                },
                error
            );
        }
    }

    async syncData(dataKey, useDebounce = true) {
        await this.ensureInitialized();
        recordDebugLog(`[syncService] Sync requested for ${dataKey}, useDebounce: ${useDebounce}`);

        const callback = async () => {
            try {
                await this._syncData(dataKey);
            } catch (error) {
                const currentRetries = this.retryCount.get(dataKey) || 0;
                if (currentRetries < 1) {
                    recordDebugLog(`Retrying sync for ${dataKey} (attempt ${currentRetries + 1})...`);
                    this.retryCount.set(dataKey, currentRetries + 1);
                    await new Promise(resolve => setTimeout(resolve, 5000));
                    return this.syncData(dataKey, useDebounce);
                }
                this.retryCount.delete(dataKey);
                throw error;
            }
        };

        const delay = this.config.syncDataOptions?.[dataKey]?.debounceMs;

        if (useDebounce) {
            return syncLock.getDeferredFn(dataKey, 'sync', callback, delay, 'debounce')();
        } else {
            return syncLock.executeWithLock(dataKey, 'sync', callback);
        }
    }

    static async getInstance() {
        if (!this.instance) {
            const syncConfig = await SyncService.prototype.loadConfig();
            this.instance = new SyncService(syncConfig);
            await this.instance.initialize();
        }
        return this.instance;
    }

    static isReinitializing = false;

    static async reinitialize() {
        if (this.isReinitializing) {
            recordDebugLog('[syncService] Reinitialization in progress, skipping...');
            throw new Error('SyncService reinitialization in progress');
        }

        try {
            this.isReinitializing = true;
            if (this.instance) {
                await this.instance.cleanup();
                this.instance = null;
            }
            return await this.getInstance();
        } finally {
            this.isReinitializing = false;
            recordDebugLog('[syncService] Reinitialization lock released');
        }
    }

    async loadConfig() {
        let retryCount = 0;
        const maxRetries = 3;

        const getSyncConfig = async () => {
            try {
                const { syncConfig } = await getUserConfig("user_settings");
                const syncMode = await getUserConfig('syncMode');
                if (!syncMode) {
                    await setUserConfig('syncMode', SYNC.MODES.DISABLED);
                }

                if (!syncConfig) {
                    throw new Error('Invalid sync config');
                }

                recordDebugLog('[syncService] Successfully loaded sync config');
                return { ...syncConfig, syncMode };
            } catch (error) {
                if (retryCount < maxRetries) {
                    retryCount++;
                    recordDebugLog(`[syncService] Retrying to get sync config (${retryCount}/${maxRetries})`);
                    await new Promise(resolve => setTimeout(resolve, 1000));
                    return getSyncConfig();
                }
                throw error;
            }
        };

        return getSyncConfig();
    }

}

// 导出方法
export const getSyncService = async () => {
    try {
        return await SyncService.getInstance();
    } catch (error) {
        recordDebugLog('[syncService] Failed to get instance:', error);
        return null;
    }
};

export const reinitializeSyncService = async () => {
    try {
        await new Promise(resolve => setTimeout(resolve, 200));
        return await SyncService.reinitialize();
    } catch (error) {
        console.error('Failed to reinitialize SyncService:', error);
        throw error;
    }
};

export const runSync = async (dataKey) => {
    const syncService = await getSyncService();
    if (syncService) {
        await syncService.syncData(dataKey, true);
    }

}

export const runSyncNow = async (dataKey) => {
    const syncService = await getSyncService();
    if (syncService) {
        await syncService.syncData(dataKey, false);
    }
}

export const runSyncAll = async (useDebounce) => {
    const syncService = await getSyncService();
    if (syncService) {
        await syncService.syncAllData(useDebounce)
    }
}
