import { recordDebugLog } from '../../../utils/helpers';
import { httpDownload, httpRequestJSON, httpUpload } from '../../../utils/http';
import BaseSyncProvider from './baseSyncProvider';
import { SyncError, ERROR_CODES } from '../errors';

export default class CustomServerProvider extends BaseSyncProvider {
    constructor(config) {
        super(config);
    }

    async uploadFile(data_type, file, metadata) {
        try {
            recordDebugLog(`Uploading ${data_type} to custom server...`);
            const response = await httpUpload({
                url: this.config.uploadEndpoint || `${process.env.BASE_API}/api/v1/sync/upload`,
                file,
                params: { data_type, ...metadata },
                headers: {
                    ...this.config.headers,
                }
            });

            recordDebugLog(`Upload successful for ${data_type}`, response);
            return response.data;
        } catch (error) {
            recordDebugLog(`Upload failed for ${data_type}:`, error);
            throw new SyncError(ERROR_CODES.SYNC_UPLOAD_ERROR, {
                dataType: data_type,
                message: error.message
            }, error);
        }
    }

    async putFile(url, file, headers = {}) {
        try {
            recordDebugLog('Uploading file...');
            const response = await fetch(url, {
                method: 'PUT',
                headers: {
                    ...headers,
                    'Content-Type': 'application/octet-stream',
                    'Cache-Control': 'private'
                },
                body: file,
            });

            if (!response.ok) {
                throw new Error(`Upload failed with status ${response.status}`);
            }
            recordDebugLog('File upload successful');
        } catch (error) {
            throw new SyncError(ERROR_CODES.SYNC_UPLOAD_ERROR, {
                message: error.message
            }, error);
        }
    }

    async getUpload(data_type) {
        try {
            recordDebugLog(`Getting upload URL for ${data_type}...`);
            const response = await httpRequestJSON({
                url: this.config.uploadEndpoint || `${process.env.BASE_API}/api/v1/sync/upload`,
                method: 'get',
                params: { data_type },
                headers: this.config.headers,
            });

            if (response.code === 0) {
                return response.data;
            }
            throw new Error(`Failed to get upload URL: ${response.message}`);
        } catch (error) {
            throw new SyncError(ERROR_CODES.SYNC_GET_UPLOAD_URL_ERROR, {
                dataType: data_type,
                message: error.message
            }, error);
        }
    }

    async downloadFile(url) {
        if (!url) {
            recordDebugLog('Download URL not provided');
            return null;
        }

        try {
            recordDebugLog('Downloading file...');
            const data = await httpDownload({
                url,
                useAuth: false,
                headers: {
                    ...this.config.headers,
                    'Cache-Control': 'no-cache, no-store, must-revalidate'
                },
            });
            recordDebugLog('Download successful');
            return data;
        } catch (error) {
            recordDebugLog('Download failed:', error);
            throw new SyncError(ERROR_CODES.SYNC_DOWNLOAD_ERROR, {
                message: error.message
            }, error);
        }
    }

    async downloadMetadata(data_type) {
        try {
            recordDebugLog(`Fetching metadata for ${data_type}...`);
            const response = await httpRequestJSON({
                url: this.config.metadataEndpoint || `${process.env.BASE_API}/api/v1/sync/metadata`,
                method: 'get',
                params: { data_type },
                headers: {
                    ...this.config.headers,
                    'Cache-Control': 'private'
                },
            });

            if (response.code === 0) {
                recordDebugLog(`Metadata fetched successfully for ${data_type}`);
                return response.data;
            }
            recordDebugLog(`No metadata found for ${data_type}`);
            return null;
        } catch (error) {
            recordDebugLog(`Failed to fetch metadata for ${data_type}:`, error);
            return null;
        }
    }

    async uploadMetadata(metadata) {
        try {
            recordDebugLog(`Updating metadata for ${metadata?.data_type}...`);

            const response = await httpRequestJSON({
                url: this.config.metadataEndpoint || `${process.env.BASE_API}/api/v1/sync/metadata`,
                method: 'post',
                params: metadata,
                headers: {
                    ...this.config.headers,
                    'Cache-Control': 'private'
                },
            });

            if (response.code === 0) {
                recordDebugLog(`Metadata updated successfully for ${metadata?.data_type}`);
                return response.data;
            }
            throw new Error(`Failed to update metadata: ${response.message}`);
        } catch (error) {
            throw new SyncError(ERROR_CODES.SYNC_UPDATE_METADATA_ERROR, {
                dataType: metadata?.data_type,
                message: error.message
            }, error);
        }
    }

    async clean() {
        try {
            recordDebugLog('Cleaning up server data...');

            const response = await httpRequestJSON({
                url: this.config.cleanEndpoint || `${process.env.BASE_API}/api/v1/sync/clean`,
                method: 'post',
                headers: {
                    ...this.config.headers,
                    'Cache-Control': 'private'
                },
            });

            if (response.code === 0) {
                recordDebugLog('Server cleanup successful');
                return true;
            }
            throw new Error(`Failed to clean server: ${response.message}`);
        } catch (error) {
            recordDebugLog('Server cleanup failed:', error);
            throw new SyncError(ERROR_CODES.SYNC_CLEAN_ERROR, {
                message: error.message
            }, error);
        }
    }
}