import { formatLocalTime, recordDebugLog } from '../../../utils/helpers';
import { processData } from './dataProcessor';
import { getCurrentUserUUID } from '../../user';
import { getLocalData, saveLocalData } from './localDataFetcher';
import { mergeObjectData, mergeArrayData, mergeHostBasedData, deepMerge } from './configMerger';
import { calculateDataHash } from './crypto';
import { ERROR_CODES, SyncError } from '../errors';

// Helper function to standardize the upload process
async function performUpload(provider, dataKey, processedData, metadata) {
    recordDebugLog(`[syncService] [${dataKey}] Starting upload process...`);

    // Check file size
    if (processedData.size > 50 * 1024 * 1024) { // 50MB in bytes
        throw new Error(`File size exceeds 50MB limit for ${dataKey}`);
    }

    // Get upload URL and metadata
    const uploadInfo = await provider.getUpload(dataKey);
    // Upload file using the provided URL
    await provider.putFile(uploadInfo.url, processedData, uploadInfo.headers);
    // Update metadata after successful upload
    await provider.uploadMetadata({
        data_type: dataKey,
        file_path: uploadInfo.file_path,
        hash: metadata.hash,
        timestamp: metadata.timestamp,
        deviceName: metadata.deviceName
    });
}

export async function handleDownloadOnlySync({
    provider,
    localCache,
    dataKey,
}) {
    const metadata = await provider?.downloadMetadata(dataKey);
    recordDebugLog(`[syncService] [${dataKey}]  download metadata...`, metadata);
    const remoteHash = metadata?.hash;
    const isActiveDevice = metadata?.device_id === await getCurrentUserUUID();
    const cachedRemoteHash = await localCache.get(`${dataKey}_remote_hash`);
    recordDebugLog(`[syncService] [${dataKey}] Processing download-only mode...`);
    // 简化下载条件：只在远程hash与本地不同且非活动设备时下载
    if (!isActiveDevice && remoteHash && remoteHash !== cachedRemoteHash) {
        try {
            recordDebugLog(`[syncService] [${dataKey}] Downloading remote data...`);
            const blob = await provider.downloadFile(metadata?.url);
            if (blob instanceof Blob) {
                const remoteData = await processData(blob, 'decompress');
                // 计算远程数据的hash
                remoteData.hash = await calculateDataHash(dataKey, remoteData.items);
                // 保存远程数据和更新hash
                await saveLocalData(localCache, dataKey, remoteData, true);
                await localCache.set(`${dataKey}_remote_hash`, remoteHash);
                await localCache.set(`${dataKey}_local_hash`, remoteHash);
                recordDebugLog(`[syncService] [${dataKey}] Downloaded and saved successfully`);
            }
        } catch (error) {
            recordDebugLog(`[syncService] [${dataKey}] Failed to get remote data: ${error.message}`);
            throw error;
        }
    } else {
        recordDebugLog(`[syncService] [${dataKey}] Remote data unchanged or active device, skipping download`);
    }
}

export async function handleUploadOnlySync({
    provider,
    localCache,
    dataKey,
    now
}) {
    let localData = await getLocalData(dataKey, localCache);
    const localHash = localData?.hash;
    const cachedLocalHash = await localCache.get(`${dataKey}_local_hash`);

    recordDebugLog(`[syncService] [${dataKey}] Processing upload-only mode...`);
    if (localHash && localHash !== cachedLocalHash) {
        try {
            recordDebugLog(`[syncService] [${dataKey}] Local data changed, uploading...`);
            const processedData = await processData(localData, 'compress');
            localData.hash = await calculateDataHash(dataKey, localData.items);

            await performUpload(provider, dataKey, processedData, {
                hash: localData.hash,
                timestamp: localData.timestamp,
                deviceName: localData.deviceName
            });

            await saveLocalData(localCache, dataKey, localData, false);
            await localCache.set(`${dataKey}_local_hash`, localHash);
            await localCache.set(`${dataKey}_last_upload_status`, 'success');
            await localCache.set(`${dataKey}_last_sync_at`, now);
            recordDebugLog(`[syncService] [${dataKey}] Upload completed successfully`);
        } catch (error) {
            await localCache.set(`${dataKey}_last_upload_status`, 'failed');
            recordDebugLog(`[syncService] [${dataKey}] Upload failed: ${error.message}`);
            throw error;
        }
    } else {
        recordDebugLog(`[syncService] [${dataKey}] Local data unchanged, skipping upload`);
    }
}

export async function handleTwoWaySync({
    provider,
    localCache,
    dataKey,
    now
}) {

    const syncLock = await localCache.get(`${dataKey}_sync_lock`);
    if (syncLock && Date.now() - syncLock < 30000) { // 30秒锁
        recordDebugLog(`[syncService] [${dataKey}] Processing two-way sync locked!`);
    }
    try {
        const metadata = await provider?.downloadMetadata(dataKey);
        recordDebugLog(`[syncService] [${dataKey}]  download metadata...`, metadata);
        await localCache.set(`${dataKey}_sync_lock`, Date.now());

        let localData = await getLocalData(dataKey, localCache);
        const localHash = localData?.hash;
        const remoteHash = metadata?.hash;
        const cachedRemoteHash = await localCache.get(`${dataKey}_remote_hash`);
        const cachedLocalHash = await localCache.get(`${dataKey}_local_hash`);
        const isActiveDevice = metadata?.device_id === await getCurrentUserUUID();
        const isFirstSync = !localData?.timestamp;

        recordDebugLog(`[syncService] [${dataKey}] Processing two-way sync mode...`, {
            localHash,
            remoteHash,
            cachedRemoteHash,
            cachedLocalHash,
            isActiveDevice,
            localSyncAt: localData?.timestamp ? `${localData.timestamp}: ${formatLocalTime(localData.timestamp)}` : 'none',
            remoteSyncAt: metadata?.timestamp ? `${metadata.timestamp}: ${formatLocalTime(metadata.timestamp)}` : 'none',
            now
        });

        // Special handling for windowTabs

        if (dataKey === 'windowTabs') {
            recordDebugLog(`[syncService] [${dataKey}] check Download windowTabs...`, {
                isActiveDevice,
                remoteHash,
                cachedRemoteHash,
            });
            // Step 1: Download remote tabs for non-active devices
            if (!isActiveDevice && remoteHash && remoteHash !== cachedRemoteHash) {
                try {
                    recordDebugLog(`[syncService] [${dataKey}] Downloading remote windowTabs...`, {
                        remoteHash,
                        cachedRemoteHash,
                        isActiveDevice
                    });
                    const blob = await provider.downloadFile(metadata?.url);
                    if (blob instanceof Blob) {
                        const remoteData = await processData(blob, 'decompress');
                        // 计算远程数据的hash
                        remoteData.hash = await calculateDataHash(dataKey, remoteData.items);
                        recordDebugLog(`[syncService] [${dataKey}] Remote data processed`, {
                            remoteDataHash: remoteData.hash,
                            itemCount: remoteData.items?.length
                        });
                        // Save remote data first
                        await saveLocalData(localCache, dataKey, remoteData, true);
                        await localCache.set(`${dataKey}_remote_hash`, remoteHash);
                        await localCache.set(`${dataKey}_local_hash`, remoteHash);
                        recordDebugLog(`[syncService] [${dataKey}] Remote windowTabs saved successfully`);
                    }
                } catch (error) {
                    recordDebugLog(`[syncService] [${dataKey}] Failed to get remote data: ${error.message}`, {
                        error: error.stack
                    });
                    throw error;
                }
            }

            // Step 2: Always upload current window tabs if they've changed
            // This ensures the current device's tabs are always shared
            recordDebugLog(`[syncService] [${dataKey}] check Uploading current windowTabs...`, {
                localHash,
                cachedLocalHash
            });
            if (localHash && localHash !== cachedLocalHash) {
                try {
                    recordDebugLog(`[syncService] [${dataKey}] Uploading current windowTabs...`, {
                        localHash,
                        cachedLocalHash,
                        itemCount: localData.items?.length
                    });
                    const processedData = await processData(localData, 'compress');
                    // 确保使用新的hash计算方法
                    localData.hash = await calculateDataHash(dataKey, localData.items);
                    recordDebugLog(`[syncService] [${dataKey}] Local data processed for upload`, {
                        newHash: localData.hash,
                        timestamp: localData.timestamp
                    });

                    await performUpload(provider, dataKey, processedData, {
                        hash: localData.hash,
                        timestamp: localData.timestamp,
                        deviceName: localData.deviceName
                    });

                    await Promise.all([
                        localCache.set(`${dataKey}_local_hash`, localHash),
                        localCache.set(`${dataKey}_remote_hash`, localHash), // 也更新remote_hash
                        localCache.set(`${dataKey}_last_upload_status`, 'success'),
                        localCache.set(`${dataKey}_last_sync_at`, now)
                    ]);
                    recordDebugLog(`[syncService] [${dataKey}] Current windowTabs uploaded successfully`, {
                        uploadedHash: localHash,
                        syncTime: now
                    });
                } catch (error) {
                    await localCache.set(`${dataKey}_last_upload_status`, 'failed');
                    recordDebugLog(`[syncService] [${dataKey}] Failed to upload current tabs: ${error.message}`, {
                        error: error.stack
                    });
                    throw error;
                }
            }
            return;
        }
        // If no remote data exists, or this is the first sync, upload local data directly
        const hasUpdate = await localCache.get(`${dataKey}_has_update`);
        hasUpdate && await localCache.remove(`${dataKey}_has_update`);

        if ((!remoteHash && localHash) || (isActiveDevice && hasUpdate && !isFirstSync)) {
            recordDebugLog(`[syncService] [${dataKey}] Uploading local data...`, {
                reason: !remoteHash ? 'No remote data exists' : 'Active device with local changes',
                isActiveDevice,
                remoteHash,
                localHash,
                cachedLocalHash
            });

            try {
                localData.timestamp = now;
                const processedData = await processData(localData, 'compress');
                await performUpload(provider, dataKey, processedData, {
                    hash: localData.hash,
                    timestamp: localData.timestamp,
                    deviceName: localData.deviceName
                });

                await Promise.all([
                    localCache.set(`${dataKey}_local_hash`, localHash),
                    localCache.set(`${dataKey}_remote_hash`, localHash),
                    localCache.set(`${dataKey}_last_upload_status`, 'success'),
                    localCache.set(`${dataKey}_last_sync_at`, now)
                ]);
                recordDebugLog(`[syncService] [${dataKey}] Local data uploaded successfully`);
                return true;
            } catch (error) {
                recordDebugLog(`[syncService] [${dataKey}] Failed to upload local data:`, error);
                await localCache.set(`${dataKey}_last_upload_status`, 'failed');
                throw error;
            }
        }

        // 如果数据已同步，跳过
        if (localHash && remoteHash && remoteHash === localHash) {
            recordDebugLog(`[syncService] [${dataKey}] Data is in sync, skipping`);
            return;
        }



        // 下载远程数据（如果需要）
        let remoteData = null;
        if (!isActiveDevice && remoteHash && remoteHash !== localHash) {
            try {
                recordDebugLog(`[syncService] [${dataKey}] Downloading remote data...`);
                const blob = await provider.downloadFile(metadata?.url);
                if (blob instanceof Blob) {
                    remoteData = await processData(blob, 'decompress');
                    await localCache.set(`${dataKey}_remote_hash`, remoteHash);
                    recordDebugLog(`[syncService] [${dataKey}] Downloaded successfully`);
                }
            } catch (error) {
                recordDebugLog(`[syncService] [${dataKey}] Failed to get remote data: ${error.message}`);
                throw error;
            }
        }

        // 合并数据
        const mergedData = await mergeSyncData(dataKey, localData, remoteData, now);
        if (!mergedData?.items) {
            recordDebugLog(`[syncService] [${dataKey}] No merged data to process`);
            return;
        }

        // 处理设备名称
        mergedData.deviceName = localData?.deviceName;

        const mergedHash = await calculateDataHash(dataKey, mergedData.items);

        if (mergedHash !== localHash) {
            mergedData.hash = mergedHash;
            await localCache.set(`${dataKey}_last_sync_at`, now);
            await saveLocalData(localCache, dataKey, mergedData, !isActiveDevice);
        }

        // 只在合并后的数据确实有变化时才上传
        if (mergedHash !== remoteHash && !isFirstSync) {
            recordDebugLog(`[syncService] [${dataKey}] Merged data differs from both local and remote, uploading...`);
            recordDebugLog(`[syncService] [${dataKey}] Merged data:`, mergedData);

            try {
                const processedData = await processData(mergedData, 'compress');
                await performUpload(provider, dataKey, processedData, {
                    hash: mergedData.hash,
                    timestamp: mergedData.timestamp,
                    deviceName: mergedData.deviceName
                });

                // Update all statuses
                await Promise.all([
                    localCache.set(`${dataKey}_local_hash`, mergedHash),
                    localCache.set(`${dataKey}_remote_hash`, mergedHash),
                    localCache.set(`${dataKey}_last_upload_status`, 'success'),

                ]);
                recordDebugLog(`[syncService] [${dataKey}] Sync completed successfully`);
                return true;
            } catch (error) {
                await localCache.set(`${dataKey}_last_upload_status`, 'failed');
                recordDebugLog(`[syncService] [${dataKey}] Failed to upload merged data: ${error.message}`);
                throw error;
            }
        } else {
            recordDebugLog(`[syncService] [${dataKey}] No changes to sync`);
            return false;
        }

    } finally {
        localCache.set(`${dataKey}_last_sync_at`, now)
        await localCache.remove(`${dataKey}_sync_lock`);
    }

}

export async function mergeSyncData(dataKey, localData, remoteData, now) {
    recordDebugLog(`[syncService] Merging sync data for ${dataKey}...`);
    recordDebugLog(`[syncService] [${dataKey}] Local data:`, localData);
    recordDebugLog(`[syncService] [${dataKey}] Remote data:`, remoteData);

    // 如果没有数据需要合并
    if (!localData?.items && !remoteData?.items) {
        recordDebugLog(`[syncService] [${dataKey}] No data to merge`);
        return null;
    }

    // 如果只有一方有数据
    if (!remoteData?.items) {
        recordDebugLog(`[syncService] [${dataKey}] No remote data, using local data`);
        return { ...localData, timestamp: now };
    }
    if (!localData?.items) {
        recordDebugLog(`[syncService] [${dataKey}] No local data, using remote data`);
        return { ...remoteData, timestamp: now };
    }

    // 首次同步：本地数据没有timestamp
    const isFirstSync = !localData?.timestamp;

    if (isFirstSync) {
        recordDebugLog(`[syncService] [${dataKey}] First sync, merging data...`);
        let items;
        switch (dataKey) {
            case 'windowTabs':
                items = mergeArrayData(localData, remoteData);
                break;
            case 'settings':
                items = mergeObjectData(localData, remoteData);
                break;
            case 'siteConfigs':
                items = mergeHostBasedData(localData, remoteData);
                break;
            case 'quickAccess':
                items = Array.from(new Set([...(localData?.items || []), ...(remoteData?.items || [])].map(item => JSON.stringify(item))))
                    .map(item => JSON.parse(item))
                    .filter(item => item.uuid);
                break;
            case 'recentClosedTabs':
                items = mergeArrayData(localData, remoteData);
                break;
            default:
                return null;
        }

        if (items) {
            const hash = await calculateDataHash(dataKey, items);
            return {
                items,
                timestamp: now,
                hash,
                deviceName: localData.deviceName || remoteData.deviceName
            };
        }

    } else {
        // 非首次同步：使用较新的数据
        recordDebugLog(`[syncService] [${dataKey}] Using newer data...`);
        recordDebugLog(`[syncService] [${dataKey}] Local timestamp: ${localData.timestamp}: ${formatLocalTime(localData.timestamp)}, Remote timestamp: ${remoteData.timestamp}: ${formatLocalTime(remoteData.timestamp)}`);
        let items;
        switch (dataKey) {
            case 'recentClosedTabs':
                items = mergeArrayData(localData, remoteData);
                if (items) {
                    const hash = await calculateDataHash(dataKey, items);
                    return {
                        items,
                        timestamp: now,
                        hash,
                        deviceName: localData.deviceName || remoteData.deviceName
                    };
                }
                return null;
            default:

                if (localData.timestamp >= remoteData.timestamp) {
                    recordDebugLog(`[syncService] [${dataKey}] Using local data`);
                    return { ...localData, timestamp: now };
                } else {
                    recordDebugLog(`[syncService] [${dataKey}] Using remote data`);
                    return { ...remoteData, timestamp: now };
                }
        }



    }

    return null;
}