import { sendRuntimeMessage } from "../../core/browers/runtime";
import { getCurrentUserUUID, getUserConfig, setAccessToken, setUserInfo } from "../../core/user";




export const handleWebsiteMessage = () => {
    chrome.runtime.onMessageExternal.addListener(async (message, sender, sendResponse) => {
        console.debug("handleWebsiteMessage", { message, sender });

        try {
            switch (message.action) {
                case 'user_logged_in':
                    await handleUserLogin(message.data);
                    await sendRuntimeMessage("user_logged_in", { user: message.data.user });
                    sendResponse({ success: true });
                    break;
                case 'user_logged_out':
                    await sendRuntimeMessage("user_logged_out");
                    sendResponse({ success: true });
                    break;
                default:
                    sendResponse({ success: false, error: 'Unknown action' });
            }
        } catch (error) {
            console.error("Error in handleWebsiteMessage:", error);
            sendResponse({ success: false, error: error.message });
        }
    });
};


const handleUserLogin = async ({ access_token, user }) => {
    if (access_token) await setAccessToken(access_token);
    if (user) await setUserInfo(user);
};
