import historyStore from "../../core/stores/historyStore";
import snapshotStore, { getCachedWindows } from "../../core/stores/snapshotStore";
import { localCacheMetadataInstance } from "../../core/stores/tabStore";
import { getSyncService } from "../../core/sync/syncService";
import { fetchUserInfo, getUserConfig, setUserConfig } from "../../core/user";
import { httpRequestJSON } from "../../utils/http";



export const handleOnStartup = async () => {
    console.log("chrome runtime onStartup ");
    const cacheInstance = await localCacheMetadataInstance();
    cacheInstance.prune();
    const cachedWindows = await getCachedWindows();
    console.log("cachedWindows", cachedWindows);
    if (cachedWindows) {
        await snapshotStore.getState().addSnapshot(cachedWindows, true);
    }
    await resetDeviceRegistered();
    await fetchUserInfo();
    await historyStore.getState().cleanupOldHistories();
    const syncService = await getSyncService();
    if (syncService) {
        await syncService.syncAllData(false);
    }

}



export const resetDeviceRegistered = async () => {
    const install_at = await getUserConfig("install_at");

    try {
        const response = await httpRequestJSON({
            url: `${process.env.BASE_API}/api/v1/device/query/registered`,
            method: "get",
        });
        console.info("resetDeviceRegistered query device registration:", response);

        if (response.code === 0) {
            const registered_at = response.data.registered_at;
            if (!registered_at) {
                await setUserConfig("install_at", new Date().toISOString());
            }
            if (install_at !== registered_at) {
                await setUserConfig("install_at", new Date(registered_at).toISOString());
            }
        } else {
            console.error("Failed to query device registration:", response.data);
        }
    } catch (error) {
        console.error("Error resetting extension registration:", error);
    }
}
