import { recordDebugLog } from '../../../utils/helpers';
import { getUserConfig } from '../../user';
import { getCurrentWindow } from '../../browers/windows';
import { snapshotStore } from '../../stores/snapshotStore';

export async function getWindowTabsData() {
    try {
        const windows = await chrome.windows.getAll({
            populate: true,
            windowTypes: ['normal']
        });
        const groups = await chrome.tabGroups.query({});

        return windows.map(window => ({
            id: window.id,
            width: window.width,
            height: window.height,
            left: window.left,
            top: window.top,
            tabs: window.tabs.map(tab => ({
                id: tab.id,
                title: tab.title.substring(0, 200),
                url: tab.url,
                active: tab.active,
                discarded: tab.discarded,
                index: tab.index,
                pinned: tab.pinned,
                windowId: tab.windowId,
                favIconUrl: tab.favIconUrl,
                groupId: tab.groupId
            })),
            groups: groups.filter(group => {
                return window.tabs.some(tab => tab.groupId === group.id);
            }).map(group => ({
                id: group.id,
                title: group.title,
                windowId: group.windowId,
                collapsed: group.collapsed,
                color: group.color
            }))
        }));
    } catch (error) {
        recordDebugLog(`[syncService] [windowTabs] Failed to get window tabs data: ${error.message}`);
        return null;
    }
}

export async function applyWindowTabs(dataKey, localCache) {
    try {
        const cachedData = await localCache.get(dataKey);

        if (!cachedData?.items) {
            recordDebugLog(`[syncService] [${dataKey}] No cached window tabs data to apply`, { dataKey, cachedData });
            return;
        }

        const settings = await getUserConfig('user_settings');
        const applyMode = settings?.syncConfig?.syncDataOptions?.windowTabs?.applyMode;
        const currentWindow = await getCurrentWindow();
        const allWindows = await chrome.windows.getAll({ populate: true });

        // Helper function to check if two windows have same tabs
        const hasSameTabs = (windowData, existingWindow) => {
            const windowUrls = new Set(windowData.tabs.map(tab => tab.url));
            const existingUrls = new Set(existingWindow.tabs.map(tab => tab.url));

            if (windowUrls.size !== existingUrls.size) return false;

            for (const url of windowUrls) {
                if (!existingUrls.has(url)) return false;
            }
            return true;
        };

        // Helper function to create a new window if no duplicate exists
        const createWindowIfUnique = async (windowData) => {
            // Check if window has valid tabs
            const validUrls = windowData.tabs.filter(tab =>
                tab.url &&
                tab.url !== 'about:blank' &&
                tab.url !== 'chrome://newtab/'
            ).map(tab => tab.url);
            if (validUrls.length === 0) {
                recordDebugLog(`[syncService] [${dataKey}] No valid tabs to create window with, skipping creation`);
                return null;
            }

            // Check if window with same tabs already exists
            const existingWindow = allWindows.find(w => hasSameTabs(windowData, w));
            if (existingWindow) {
                recordDebugLog(`[syncService] [${dataKey}] Window with same tabs already exists, skipping creation`);
                return existingWindow;
            }

            const newWindow = await chrome.windows.create({
                width: windowData.width,
                height: windowData.height,
                left: windowData.left,
                top: windowData.top,
                url: validUrls
            });

            const newTabs = await chrome.tabs.query({ windowId: newWindow.id });

            // Update tab properties and handle discarded state
            for (const [index, tab] of newTabs.entries()) {
                const tabData = windowData.tabs[index];
                if (!tabData) continue;

                const updateProps = {
                    pinned: tabData.pinned,
                    active: tabData.active
                };

                await chrome.tabs.update(tab.id, updateProps);

                if (tabData.discarded) {
                    // Add listener for tab update to discard after title is loaded
                    const listener = (tabId, changeInfo) => {
                        if (tabId === tab.id && (changeInfo.status === 'complete' || changeInfo.title)) {
                            chrome.tabs.discard(tab.id);
                            chrome.tabs.onUpdated.removeListener(listener);
                        }
                    };
                    chrome.tabs.onUpdated.addListener(listener);
                }
            }

            // Restore groups
            if (windowData.groups?.length > 0) {
                for (const group of windowData.groups) {
                    const groupTabs = newTabs.filter((_, index) =>
                        windowData.tabs[index].groupId === group.id
                    );

                    if (groupTabs.length > 0) {
                        const newGroup = await chrome.tabGroups.create({
                            windowId: newWindow.id,
                            tabIds: groupTabs.map(tab => tab.id)
                        });

                        await chrome.tabGroups.update(newGroup.id, {
                            collapsed: group.collapsed,
                            color: group.color,
                            title: group.title
                        });
                    }
                }
            }

            return newWindow;
        };

        // Move declarations outside the switch statement
        const { addSnapshot } = snapshotStore.getState();

        // Transform cached data into snapshot format
        const timestamp = Date.now();
        const snapshotData = {
            deviceName: cachedData.deviceName || "Remote",
            createdAt: timestamp,
            windowCount: cachedData.items.length,
            tabCount: cachedData.items.reduce((acc, window) => acc + window.tabs.length, 0),
            isAutoCreated: false,
            windows: cachedData.items.map(windowData => ({
                ...windowData,
                type: 'normal',
                state: 'normal',
                focused: false,
                alwaysOnTop: false,
                tabs: windowData.tabs
                    .filter(tab => tab?.url && !tab.pinned)
                    .map(tab => ({
                        ...tab,
                        highlighted: false,
                        incognito: false,
                        selected: false,
                        windowId: windowData.id
                    })),
                tabGroups: windowData.groups?.map(group => ({
                    id: group.id,
                    title: group.title,
                    windowId: windowData.id,
                    collapsed: group.collapsed,
                    color: group.color
                })) || []
            })).filter(window => window.tabs.length > 0)
        };

        switch (applyMode) {
            case 'new': {
                // Create new windows with tabs if they don't exist
                for (const windowData of cachedData.items) {
                    await createWindowIfUnique(windowData);
                }
                break;
            }

            case 'append': {
                // Move declarations outside case block
                const targetWindow = currentWindow || allWindows[0];
                if (!targetWindow || !cachedData.items.length) break;

                const currentTabs = await chrome.tabs.query({ windowId: targetWindow.id });
                const shouldAppendToCurrentWindow = currentTabs.length < 5;

                if (shouldAppendToCurrentWindow) {
                    // Append first window's tabs to current window
                    const firstWindowData = cachedData.items[0];
                    const validTabs = firstWindowData.tabs.filter(tab =>
                        tab.url &&
                        tab.url !== 'about:blank' &&
                        tab.url !== 'chrome://newtab/'
                    );

                    if (validTabs.length === 0) {
                        recordDebugLog(`[syncService] [${dataKey}] No valid tabs to append`);
                        break;
                    }

                    // Get existing URLs in target window
                    const existingUrls = new Set(currentTabs.map(tab => tab.url));

                    // Create tabs in target window, skipping duplicates
                    const createdTabs = await Promise.all(
                        validTabs
                            .filter(tab => !existingUrls.has(tab.url))
                            .map(async tab => {
                                const newTab = await chrome.tabs.create({
                                    windowId: targetWindow.id,
                                    url: tab.url,
                                    pinned: tab.pinned,
                                    active: tab.active
                                });

                                if (tab.discarded) {
                                    // Add listener for tab update to discard after title is loaded
                                    const listener = (tabId, changeInfo) => {
                                        if (tabId === newTab.id && (changeInfo.status === 'complete' || changeInfo.title)) {
                                            chrome.tabs.discard(newTab.id);
                                            chrome.tabs.onUpdated.removeListener(listener);
                                        }
                                    };
                                    chrome.tabs.onUpdated.addListener(listener);
                                }

                                return newTab;
                            })
                    );

                    // Restore groups
                    if (firstWindowData.groups?.length > 0) {
                        for (const group of firstWindowData.groups) {
                            const groupTabs = createdTabs.filter((_, index) =>
                                firstWindowData.tabs[index].groupId === group.id
                            );

                            if (groupTabs.length > 0) {
                                const newGroup = await chrome.tabGroups.create({
                                    windowId: targetWindow.id,
                                    tabIds: groupTabs.map(tab => tab.id)
                                });

                                await chrome.tabGroups.update(newGroup.id, {
                                    collapsed: group.collapsed,
                                    color: group.color,
                                    title: group.title
                                });
                            }
                        }
                    }
                } else {
                    // Create new window for first window's tabs if it doesn't exist
                    const firstWindowData = cachedData.items[0];
                    await createWindowIfUnique(firstWindowData);
                }

                // Create remaining windows if they don't exist
                for (let i = 1; i < cachedData.items.length; i++) {
                    await createWindowIfUnique(cachedData.items[i]);
                }
                break;
            }

            case 'replace': {
                // Move declarations outside case block
                for (const windowData of cachedData.items) {
                    await createWindowIfUnique(windowData);
                }

                // Remove old windows that don't match any of the new windows
                for (const oldWindow of allWindows) {
                    const hasMatch = cachedData.items.some(windowData =>
                        hasSameTabs(windowData, oldWindow)
                    );
                    if (!hasMatch) {
                        await chrome.windows.remove(oldWindow.id);
                    }
                }
                break;
            }

            case 'createSnapshot': {
                await addSnapshot(snapshotData, false);
                recordDebugLog(`[syncService] [${dataKey}] Created new snapshot from synced window tabs data:`, snapshotData);
                break;
            }

            default:
                throw new Error(`Unknown apply mode: ${applyMode}`);
        }

        recordDebugLog(`[syncService] [${dataKey}] Applied window tabs with mode: ${applyMode}`);
    } catch (error) {
        recordDebugLog(`[syncService] [${dataKey}] Failed to apply window tabs: ${error.message}`);
        throw error;
    }
}
