import { getAccessToken, getCurrentUserUUID } from "../core/user";
import { recordDebugLog } from "./helpers";

const REQUEST_TIMEOUT = 30000; // 10 seconds
const MAX_BACKOFF_TIME = 32000; // Maximum backoff time: 32 seconds
const REQUEST_CACHE_TTL = 5000; // 5 seconds cache TTL

// Cache for storing request responses
const requestCache = new Map();

// Cache for auth headers
const authHeadersCache = new Map();

// Helper function to get auth headers
const getAuthHeaders = async (headers = {}) => {
    const now = Date.now();
    const cacheKey = JSON.stringify(headers);

    // Return cached headers if within TTL
    const cachedHeaders = authHeadersCache.get(cacheKey);
    if (cachedHeaders && (now - cachedHeaders.timestamp < REQUEST_CACHE_TTL)) {
        return cachedHeaders.headers;
    }

    const [uuid, token, extension] = await Promise.all([getCurrentUserUUID(), getAccessToken(), chrome.management.getSelf()]);

    // Create new auth headers
    const authHeaders = {
        ...headers,
        'Authorization': `Bearer ${token}`,
        'X-Device-Id': uuid,
        'X-Extension-Id': chrome.runtime.id,
        'X-Extension-Version': extension.version,
        'X-Extension-InstallType': extension.installType,
        'User-Agent': navigator.userAgent
    };

    // Cache the headers with timestamp
    authHeadersCache.set(cacheKey, {
        timestamp: now,
        headers: authHeaders
    });

    return authHeaders;
};

// Helper function for exponential backoff
const getBackoffDelay = (retryCount) => Math.min(1000 * Math.pow(2, retryCount), MAX_BACKOFF_TIME);

const createErrorResponse = (message, details = {}) => ({
    code: -1,
    error: message,
    ...details
});

const handleResponse = async (response) => {
    const contentType = response.headers.get('content-type');
    if (contentType && contentType.includes('application/json')) {
        return await response.json();
    } else if (contentType && contentType.includes('application/octet-stream')) {
        return await response.blob();
    } else {
        return await response.text();
    }
};

const fetchWithRetry = async (url, config, retries) => {
    for (let retryCount = 0; retryCount <= retries; retryCount++) {
        try {
            const controller = new AbortController();
            const timeoutId = setTimeout(() => controller.abort(), REQUEST_TIMEOUT);
            config.signal = controller.signal;

            const response = await fetch(url, config);
            clearTimeout(timeoutId);

            if (!response.ok) {
                throw new Error(`HTTP error! status: ${response.status}`);
            }

            return await handleResponse(response);
        } catch (error) {
            if (retryCount < retries) {
                await new Promise(resolve => setTimeout(resolve, getBackoffDelay(retryCount)));
                continue;
            }
            return createErrorResponse(error.message, {
                status: error.status,
                statusText: error.statusText
            });
        }
    }
};

// Generate cache key from request parameters
const generateCacheKey = (url, method, params) => {
    return JSON.stringify({
        url,
        method: method.toUpperCase(),
        params: params || null
    });
};

export const httpRequestJSON = async ({ url, method = 'POST', params = null, retries = 1, headers = {} }) => {
    if (!url) {
        return createErrorResponse('URL is required', { url });
    }

    const cacheKey = generateCacheKey(url, method, params);
    const now = Date.now();

    // Check cache for existing request
    const cachedRequest = requestCache.get(cacheKey);
    if (cachedRequest) {
        if (now - cachedRequest.timestamp < REQUEST_CACHE_TTL) {
            // Return cached promise if within TTL
            return cachedRequest.promise;
        } else {
            // Remove expired cache entry
            requestCache.delete(cacheKey);
        }
    }

    const config = {
        method,
        headers: {
            'Content-Type': 'application/json',
            ...(await getAuthHeaders(headers))
        }
    };

    if (params) {
        if (method.toUpperCase() === 'GET') {
            const searchParams = new URLSearchParams(params);
            url = `${url}?${searchParams.toString()}`;
        } else {
            config.body = JSON.stringify(params);
        }
    }

    // Create new request promise
    const requestPromise = fetchWithRetry(url, config, retries);

    // Cache the request promise with timestamp
    requestCache.set(cacheKey, {
        timestamp: now,
        promise: requestPromise
    });

    // Clean up cache after request completes
    requestPromise.finally(() => {
        setTimeout(() => {
            requestCache.delete(cacheKey);
        }, REQUEST_CACHE_TTL);
    });

    return requestPromise;
};

export const httpUpload = async ({ url, file, params = {}, retries = 1, headers = {} }) => {
    if (!url || !file) {
        return createErrorResponse('URL and file are required', { url, file });
    }

    const formData = new FormData();
    formData.append('file', file);
    Object.entries(params).forEach(([key, value]) => formData.append(key, value));

    const config = {
        method: 'POST',
        headers: await getAuthHeaders(headers),
        body: formData
    };

    return await fetchWithRetry(url, config, retries);
};

export const httpGet = async ({ url, params = {}, headers = {}, retries = 1 }) => {
    if (!url) {
        throw new Error('URL is required');
    }

    if (Object.keys(params).length) {
        const searchParams = new URLSearchParams(params);
        url = `${url}?${searchParams.toString()}`;
    }

    const config = {
        headers: await getAuthHeaders(headers)
    };

    return await fetchWithRetry(url, config, retries);
};

export const httpDownload = async ({ url, headers = {}, retries = 1, useAuth = true }) => {
    if (!url) {
        return createErrorResponse('URL is required', { url });
    }

    const config = {
        method: 'GET',
        headers: { ...headers, ...(useAuth ? await getAuthHeaders(headers) : {}) }
    };

    const response = await fetchWithRetry(url, config, retries);

    // 如果返回的是错误对象，直接返回
    if (response.error) {
        return response;
    }

    // 如果是 Blob 对象，直接返回
    if (response instanceof Blob) {
        return response;
    }

    // 如果是字符串，尝试解析 JSON
    if (typeof response === 'string') {
        try {
            return JSON.parse(response);
        } catch (e) {
            return response;
        }
    }

    // 其他情况直接返回响应内容
    return response;
};
