import { recordDebugLog } from '../../../utils/helpers';
import { SyncError, ERROR_CODES } from '../errors';
import {
    getUserConfig,
    hasLocalPassword,
    checkIsMembership
} from '../../user';
import { t } from 'i18next';

export async function checkSyncPermissions() {
    recordDebugLog('Checking sync permissions...');

    const isUserLoggedIn = await getUserConfig('rabbitpair_is_user_logged_in');
    if (!isUserLoggedIn) {
        recordDebugLog('Error: User is not logged in');
        throw new SyncError(
            ERROR_CODES.NOT_LOGGED_IN,
            { message: t('errors.notLoggedIn') }
        );
    }

    // const hasPassword = await hasLocalPassword();
    // if (!hasPassword) {
    //     recordDebugLog('Error: No local password set');
    //     throw new SyncError(
    //         ERROR_CODES.NO_LOCAL_PASSWORD,
    //         { message: t('errors.noLocalPassword') }
    //     );
    // }

    const isMember = await checkIsMembership();
    if (!isMember) {
        recordDebugLog('Error: User is not a member');
        throw new SyncError(
            ERROR_CODES.NOT_MEMBER,
            { message: t('errors.notMember') }
        );
    }

    recordDebugLog('All permission checks passed');
    return true;
} 