import { delay } from "lodash-es";
import { setTabActive } from "./tabs";
import chromeStorage from "../../utils/chromeStorage";
import { getUserConfig } from "../user";
import { getDomainFromUrl } from "../../utils/helpers";
import { chromeGroupAvailableColors } from "../../utils/colors";

export const openGroupAndCollapseOthers = async (groupId, windowId) => {
    try {
        if (groupId > 0) {
            const group = await chrome.tabGroups?.get(groupId);
            if (!group) return;
            if (group.collapsed) {
                await chrome.tabGroups?.update(group.id, { collapsed: false });
            }
            if (!windowId) {
                windowId = group.windowId;
            }
        }

        const params = { collapsed: false };
        if (windowId) {
            params.windowId = windowId;
        }

        const openedTabGroups = await chrome.tabGroups?.query(params);
        for (const openedTabGroup of openedTabGroups) {
            if (openedTabGroup.id !== groupId) {
                await chrome.tabGroups?.update(openedTabGroup.id, { collapsed: true });
            }
        }
    } catch (error) {
        console.error("Error in openGroupAndCollapseOthers:", error);
    }
};

export const disableGroupCollapse = async (groupId) => {
    try {
        delay(async () => {
            await chrome.tabGroups?.update(groupId, { collapsed: false });
        }, 50);

        const old = await chromeStorage('session').get("ignoreEventsTabGroupIds") || [];
        await chromeStorage('session').set("ignoreEventsTabGroupIds", [...old, groupId]);
        await activeGroupFirstTab(groupId);
    } catch (error) {
        console.error("Error in disableGroupCollapse:", error);
    }
};

export const activeGroupFirstTab = async (groupId) => {
    try {
        const checkActiveLock = await chromeStorage('session').get('setLockActiveTabId');
        if (!checkActiveLock) {
            const tabs = await chrome.tabs.query({ windowType: 'normal', groupId });
            if (tabs.length > 0) {
                await setTabActive(tabs[0].id);
            }
        }
    } catch (error) {
        console.error("Error in activeGroupFirstTab:", error);
    }
};

export const groupTabsByDomain = async (windowId) => {
    const errors = [];
    try {
        const settings = await getUserConfig('user_settings');
        const tabQuery = {
            windowType: 'normal',
            pinned: settings.groupFilterOutPinnedTabs ? false : undefined,
        };

        const windows = windowId ? [{ id: windowId }] : await chrome.windows.getAll({ windowTypes: ['normal'] });

        for (const window of windows) {
            tabQuery.windowId = window.id;
            const tabs = await chrome.tabs.query(tabQuery);
            if (!tabs?.length) continue;

            const domainTabs = tabs.reduce((acc, tab) => {
                const domain = parseUrlGroupName(tab.url);
                if (!acc[domain]) acc[domain] = [];
                acc[domain].push(tab);
                return acc;
            }, {});

            for (const [domain, domainTabList] of Object.entries(domainTabs)) {
                if (domainTabList.length > 0) {
                    try {
                        const colorIndex = Object.keys(domainTabs).indexOf(domain);
                        const color = chromeGroupAvailableColors[colorIndex % chromeGroupAvailableColors.length].color;
                        const groupId = await chrome.tabs.group({
                            tabIds: domainTabList.map(tab => tab.id),
                            createProperties: { windowId: domainTabList[0].windowId }
                        });
                        await chrome.tabGroups?.update(groupId, { title: domain, color, collapsed: true });
                        await new Promise(resolve => setTimeout(resolve, 100));
                    } catch (error) {
                        console.error(`Error grouping tabs for domain ${domain}:`, error);
                        errors.push(error.message);
                    }
                }
            }
        }
    } catch (error) {
        console.error("Error grouping tabs by domain:", error);
        errors.push(error.message);
    }

    if (errors.length) {
        throw new Error(errors.join('\n'));
    }
};

export const sortTabsByDomain = async (windowId) => {
    try {
        const settings = await getUserConfig('user_settings');
        const tabQuery = {
            windowType: 'normal',
            currentWindow: settings.onlyCurrentWindowTabs || false,
            pinned: settings.groupFilterOutPinnedTabs ? false : undefined,
            windowId: windowId || undefined
        };

        const tabs = await chrome.tabs.query(tabQuery);
        if (!tabs?.length) return;

        const domainTabs = tabs.reduce((acc, tab) => {
            if (tab.groupId !== -1) return acc;
            const domain = getDomainFromUrl(tab.url);
            if (!acc[domain]) acc[domain] = [];
            acc[domain].push(tab);
            return acc;
        }, {});

        let newIndex = 0;
        const sortedDomains = Object.keys(domainTabs).sort();
        for (const domain of sortedDomains) {
            for (const tab of domainTabs[domain]) {
                await chrome.tabs.move(tab.id, { index: newIndex++ });
            }
        }
    } catch (error) {
        console.error("Error sorting tabs by domain:", error);
    }
};

export const sortTabsByURL = async (windowId) => {
    try {
        const settings = await getUserConfig('user_settings');
        const tabQuery = {
            windowType: 'normal',
            currentWindow: settings.onlyCurrentWindowTabs || false,
            pinned: settings.groupFilterOutPinnedTabs ? false : undefined,
            windowId: windowId || undefined
        };

        const tabs = await chrome.tabs.query(tabQuery);
        if (!tabs?.length) return;

        const urlTabs = tabs
            .filter(tab => tab.groupId === -1)
            .sort((a, b) => a.url.localeCompare(b.url));

        for (let i = 0; i < urlTabs.length; i++) {
            await chrome.tabs.move(urlTabs[i].id, { index: i });
        }
    } catch (error) {
        console.error("Error sorting tabs by URL:", error);
    }
};

export const parseUrlGroupName = (url) => {
    try {
        const parsedUrl = new URL(url);
        switch (parsedUrl.protocol) {
            case 'http:':
            case 'https:':
                return parsedUrl.hostname.replace("www.", '');
            case 'chrome:':
                return parsedUrl.origin;
            case 'chrome-extension:':
                return 'extension';
            case 'view-source:':
                return parsedUrl.protocol;
            default:
                return url.split('/').slice(0, 3).join('/');
        }
    } catch (error) {
        console.error("Error parseUrlGroupName:", error);
        return url.split('/').slice(0, 3).join('/');
    }
};
