import { recordDebugLog } from '../../../utils/helpers';
import { getUserConfig, setUserConfig } from "../../user";
import { userStoreCacheInstance } from '../../stores/userStore';
import { sendRuntimeMessage } from '../../browers/runtime';

export const getSettingsData = async () => {
    try {

        const settings = await getUserConfig('user_settings');
        const cacheInstance = await userStoreCacheInstance();
        const backgroundImageUrl = await cacheInstance.get("backgroundImageUrl") || "";
        const background_image_urls = await cacheInstance.get("background_image_urls") || [];

        return {
            ...settings,
            backgroundImageUrl,
            background_image_urls
        };
    } catch (error) {
        recordDebugLog(`[syncService] [settings] Failed to get settings data: ${error.message}`);
        return null;
    }
}

export async function applySettings(dataKey, localCache) {
    if (!dataKey || !localCache) {
        throw new Error('Missing required parameters');
    }

    try {
        const cachedData = await localCache.get(dataKey);

        if (!cachedData?.items) {
            recordDebugLog(`[syncService] [${dataKey}] No cached settings data to apply`, dataKey);
            return;
        }

        const userSettings = cachedData.items;
        const cacheInstance = await userStoreCacheInstance();
        await cacheInstance.set('background_image_urls', userSettings.background_image_urls || []);
        await cacheInstance.set("backgroundImageUrl", userSettings.backgroundImageUrl || "");
        delete userSettings.background_image_urls;
        delete userSettings.backgroundImageUrl;

        recordDebugLog(`[syncService] [${dataKey}] Applied  Dist settings`, userSettings);

        await setUserConfig('user_settings', userSettings);
        await sendRuntimeMessage('refresh_setting');

        recordDebugLog(`[syncService] [${dataKey}] Applied settings successfully`, dataKey);
    } catch (error) {
        recordDebugLog(`[syncService] [${dataKey}] Failed to apply settings: ${error.message}`, dataKey);
        throw error;
    }
}
