import { recordDebugLog } from '../../../utils/helpers';
import { localCacheSiteInstance, setCachedSiteConfig, siteStore } from '../../stores/siteStore';
import { sendRuntimeMessage } from '../../browers/runtime';

/**
 * Retrieves site configuration data from local cache
 * @returns {Promise<Array|null>} Array of site configs or null if error
 */
export async function getSiteConfigsData() {
    try {
        const siteConfigInstance = await localCacheSiteInstance();
        if (!siteConfigInstance) {
            recordDebugLog('[syncService] [siteConfigs] Failed to get site config instance');
            return null;
        }
        return await siteConfigInstance.all();
    } catch (error) {
        recordDebugLog(`[syncService] [siteConfigs] Failed to get site configs data: ${error.message}`);
        return null;
    }
}

/**
 * Applies site configuration data from cache
 * @param {string} dataKey - Key to retrieve data from cache
 * @param {Object} localCache - Local cache instance
 * @returns {Promise<void>}
 */
export async function applySiteConfigs(dataKey, localCache) {
    if (!dataKey || !localCache) {
        recordDebugLog(`[syncService] [${dataKey}] Invalid parameters for applying site configs`);
        return;
    }

    try {
        const cachedData = await localCache.get(dataKey);

        if (!cachedData?.items?.length) {
            recordDebugLog(`[syncService] [${dataKey}] No cached site configs data to apply`);
            return;
        }

        await siteStore.getState().restoreSiteConfigs(cachedData.items);
        await sendRuntimeMessage("refresh_site_configs");



        recordDebugLog(`[syncService] [${dataKey}] Successfully applied ${cachedData.items.length} site configs`);
    } catch (error) {
        recordDebugLog(`[syncService] [${dataKey}] Failed to apply site configs: ${error.message}`);
        throw error;
    }
}