import { isEqual, union, uniqWith, mergeWith, isArray, isObject } from 'lodash-es';

/**
 * 获取对象的唯一标识字段
 */
function getIdentifierKey(obj) {
    if (!isObject(obj) || isArray(obj)) return null;
    return ['id', 'uuid', 'type', 'name'].find(key => {
        const value = obj[key];
        return value != null && (typeof value === 'string' || typeof value === 'number');
    }) || null;
}

/**
 * 深度合并数组和对象的通用函数
 */
export function deepMerge(objValue, srcValue) {
    if (!isArray(objValue)) {
        return undefined; // 使用 lodash 默认的合并行为
    }

    const firstItem = objValue.find(Boolean) || srcValue?.find(Boolean);
    if (!firstItem || !isObject(firstItem)) {
        return uniqWith(union(objValue, srcValue), isEqual).slice(0, 100);
    }

    const key = getIdentifierKey(firstItem);
    if (!key) {
        return uniqWith(union(objValue, srcValue), isEqual).slice(0, 100);
    }

    // 对象数组按key合并
    const merged = new Map();
    [...objValue, ...(srcValue || [])].forEach(item => {
        if (!item?.[key]) return;
        merged.set(item[key],
            merged.has(item[key])
                ? mergeWith({}, merged.get(item[key]), item, deepMerge)
                : item
        );
    });

    return Array.from(merged.values())
        .sort((a, b) => (a.sort || a.index || 0) - (b.sort || b.index || 0))
        .slice(0, 100);
}

/**
 * 合并对象类型的数据
 */
export function mergeObjectData(localData, remoteData) {
    if (!localData?.items && !remoteData?.items) {
        return null;
    }
    if (!localData?.items && remoteData?.items && isObject(remoteData?.items)) {
        return remoteData.items;
    }
    if (localData?.items && isObject(localData?.items) && !remoteData?.items) {
        return localData.items;
    }

    const [newer, older] = remoteData.timestamp > localData.timestamp
        ? [remoteData, localData]
        : [localData, remoteData];

    return mergeWith({}, older.items, newer.items, deepMerge);
}

/**
 * 合并简单数组类型的数据
 */
export function mergeArrayData(localData, remoteData, compareFunc) {
    if (!Array.isArray(localData?.items) && !Array.isArray(remoteData?.items)) {
        return null;
    }

    if (!Array.isArray(localData?.items) && Array.isArray(remoteData?.items)) {
        return remoteData.items;
    }
    if (Array.isArray(localData?.items) && !Array.isArray(remoteData?.items)) {
        return localData.items;
    }
    const [newerData, olderData] = remoteData.timestamp > localData.timestamp
        ? [remoteData, localData]
        : [localData, remoteData];

    return uniqWith([...newerData.items, ...olderData.items], compareFunc);
}

/**
 * 合并基于主机名的配置数据
 */
export function mergeHostBasedData(localData, remoteData) {
    try {
        if (!Array.isArray(localData?.items) && !Array.isArray(remoteData?.items)) {
            return null;
        }
        if (!Array.isArray(localData?.items) && Array.isArray(remoteData?.items)) {
            return remoteData?.items;
        }

        if (Array.isArray(localData?.items) && !Array.isArray(remoteData?.items)) {
            return localData.items;
        }

        const [newerData, olderData] = remoteData.timestamp > localData.timestamp
            ? [remoteData, localData]
            : [localData, remoteData];

        return newerData.items.reduce((acc, newerItem) => {
            const olderItem = olderData.items.find(item => item.hostname === newerItem.hostname);
            if (olderItem) {
                const mergedItem = mergeWith({}, olderItem, newerItem, deepMerge);
                acc.push(mergedItem);
            } else {
                acc.push(newerItem);
            }
            return acc;
        }, []);

    } catch (error) {
        console.error('Error in mergeHostBasedData:', error);
        return localData.items;
    }
}

export default { mergeObjectData, mergeArrayData, mergeHostBasedData, deepMerge }; 