import { debounce, throttle } from 'lodash-es';
import { recordDebugLog } from './helpers';

class SyncLockManager {
    constructor() {
        this.debouncedFns = new Map();
        this.throttledFns = new Map();
        this.isProcessing = new Map();
        this.lastExecutionTime = new Map();
    }

    getDelay(delay) {
        return Math.max(delay || 1000, 500);
    }

    getLockKey(dataKey, action) {
        return `${dataKey}:${action}`;
    }

    getDebouncedFn(dataKey, action, callback, delay) {
        const lockKey = this.getLockKey(dataKey, action);

        if (!this.debouncedFns.has(lockKey)) {
            const actualDelay = this.getDelay(delay);
            this.debouncedFns.set(
                lockKey,
                debounce(
                    async () => {
                        try {
                            await this.executeWithLock(dataKey, action, callback);
                        } catch (error) {
                            recordDebugLog(`[syncLock] Debounced execution failed for ${lockKey}:`, error);
                        } finally {
                            this.isProcessing.set(lockKey, false);
                        }
                    },
                    actualDelay,
                    {
                        leading: false,
                        trailing: true,
                        maxWait: actualDelay * 2
                    }
                )
            );
        }
        return this.debouncedFns.get(lockKey);
    }

    getThrottledFn(dataKey, action, callback, delay) {
        const lockKey = this.getLockKey(dataKey, action);

        if (!this.throttledFns.has(lockKey)) {
            const actualDelay = this.getDelay(delay);
            this.throttledFns.set(
                lockKey,
                throttle(
                    async () => {
                        try {
                            await this.executeWithLock(dataKey, action, callback);
                        } catch (error) {
                            recordDebugLog(`[syncLock] Throttled execution failed for ${lockKey}:`, error);
                        } finally {
                            this.isProcessing.set(lockKey, false);
                        }
                    },
                    actualDelay,
                    {
                        leading: true,
                        trailing: false
                    }
                )
            );
        }
        return this.throttledFns.get(lockKey);
    }

    getDeferredFn(dataKey, action, callback, delay, type = 'debounce') {
        return type === 'throttle'
            ? this.getThrottledFn(dataKey, action, callback, delay)
            : this.getDebouncedFn(dataKey, action, callback, delay);
    }

    async executeWithLock(dataKey, action, callback) {
        const lockKey = this.getLockKey(dataKey, action);

        if (this.isProcessing.get(lockKey)) {
            recordDebugLog(`[syncLock] Operation already in progress for ${lockKey}`);
            return;
        }

        const now = Date.now();
        const lastExecution = this.lastExecutionTime.get(lockKey) || 0;
        const minInterval = this.getDelay() * 0.8;

        if (now - lastExecution < minInterval) {
            recordDebugLog(`[syncLock] Skipping operation for ${lockKey} - too soon`);
            return;
        }

        this.isProcessing.set(lockKey, true);
        try {
            await callback();
            this.lastExecutionTime.set(lockKey, Date.now());
        } catch (error) {
            recordDebugLog(`[syncLock] Error during operation for ${lockKey}:`, error);
            throw error;
        } finally {
            this.isProcessing.set(lockKey, false);
            recordDebugLog(`[syncLock] Released lock for ${lockKey}`);
        }
    }

    cleanup() {
        for (const [lockKey, fn] of this.debouncedFns.entries()) {
            try {
                if (fn?.cancel) {
                    fn.cancel();
                }
            } catch (error) {
                recordDebugLog(`[syncLock] Error cancelling debounced function for ${lockKey}:`, error);
            }
        }

        for (const [lockKey, fn] of this.throttledFns.entries()) {
            try {
                if (fn?.cancel) {
                    fn.cancel();
                }
            } catch (error) {
                recordDebugLog(`[syncLock] Error cancelling throttled function for ${lockKey}:`, error);
            }
        }

        this.debouncedFns.clear();
        this.throttledFns.clear();
        this.isProcessing.clear();
        this.lastExecutionTime.clear();
    }
}

const syncLock = new SyncLockManager();
export const cleanupSyncLock = () => syncLock.cleanup();
export default syncLock; 